@push('scripts')<script>$(function(){var tableElement=$('#purchase-orders-table'),filters=$('#po-filters'),text=$.fn.dataTable.render.text(),statuses={DRAFT:'app-status-neutral',APPROVED:'app-status-success',VOID:'app-status-danger'};window.erpInitSelect2('#po-filter-supplier',{placeholder:'ค้นหา Supplier',allowClear:true,ajax:{url:$('#po-filter-supplier').data('url'),delay:250,data:function(p){return{q:p.term||'',page:p.page||1};},processResults:function(data){return data;}}});var table=tableElement.DataTable($.extend(true,{},window.erpDataTableDefaults,{ajax:{url:'{{ route('purchasing.purchase-orders.data') }}',data:function(data){data.document_date_from=$('#po-filter-date-from').val();data.document_date_to=$('#po-filter-date-to').val();data.supplier_id=$('#po-filter-supplier').val();data.status=$('#po-filter-status').val();}},order:[[1,'desc']],buttons:[window.erpExcelButton(tableElement)],columns:[{data:'document_number',name:'document_number',render:function(value,type,row){return type==='display'?'<a class="fw-semibold link-primary" href="'+text.display(row.show_url)+'">'+text.display(value)+'</a>':value;}},{data:'document_date_label',name:'document_date',render:text.display},{data:'supplier_label',name:'supplier_id',render:text.display},{data:'purchase_requisition_label',name:'purchase_requisition_id',render:text.display},{data:'expected_date_label',name:'expected_date',render:text.display},{data:'total_amount',name:'total_amount',className:'text-end',render:$.fn.dataTable.render.number(',','.',2)},{data:'status_label',name:'status',render:function(value,type,row){return type==='display'?'<span class="badge '+(statuses[row.status]||'app-status-neutral')+'">'+text.display(value)+'</span>':row.status;}},{data:null,orderable:false,searchable:false,className:'text-end text-nowrap',render:function(value,type,row){if(type!=='display')return '';var actions=['<a class="btn btn-sm btn-app-soft" href="'+text.display(row.show_url)+'" title="ดูรายละเอียด" aria-label="ดูรายละเอียด"><i class="bx bx-file-find" aria-hidden="true"></i></a>'];if(row.edit_url)actions.push('<a class="btn btn-sm btn-app-soft" href="'+text.display(row.edit_url)+'" title="แก้ไข" aria-label="แก้ไข"><i class="bx bx-edit" aria-hidden="true"></i></a>');if(row.print_url)actions.push('<a class="btn btn-sm btn-app-soft" target="_blank" href="'+text.display(row.print_url)+'" title="พิมพ์" aria-label="พิมพ์"><i class="bx bx-printer" aria-hidden="true"></i></a>');if(row.delete_url)actions.push('<button type="button" class="btn btn-sm btn-app-danger js-delete" data-url="'+text.display(row.delete_url)+'" title="ลบร่าง" aria-label="ลบร่าง"><i class="bx bx-trash" aria-hidden="true"></i></button>');return actions.join(' ');}}]}));filters.on('change','input,select',function(){table.ajax.reload();});filters.on('click','.js-reset',function(){filters.find('input,select').val('');$('#po-filter-supplier').val(null).trigger('change');table.ajax.reload();});window.erpAjaxDelete({button:'.js-delete',reload:'#purchase-orders-table',title:'ลบร่างใบสั่งซื้อ?',text:'เอกสารร่างจะถูกลบและไม่สามารถกู้คืนได้',confirmButtonText:'ลบร่าง',cancelButtonText:'กลับ'});});</script>@endpush
